<script setup>const token=useRoute().query.token;const password=ref(''),msg=ref('');async function submit(){try{await $fetch('/api/auth/reset',{method:'POST',body:{token,password:password.value}});msg.value='Password berhasil diubah.'}catch(e){msg.value=e.data?.statusMessage||'Token tidak valid'}}</script><template><main class="max-w-md mx-auto p-8"><form class="panel space-y-4" @submit.prevent="submit"><h1 class="text-2xl font-black">Reset password</h1><input v-model="password" type="password" minlength="10" class="input" placeholder="Password baru" required><button class="btn-primary w-full">Simpan password</button><p>{{msg}}</p></form></main></template>